/**
 * Return the previous/next element of a list, skipping disabled elements.
 *
 * @param {array} list    The list of elements
 * @param activeElement   The active element
 * @param shouldGetNext   Choose to get next or previous element
 * @param isCycleAllowed
 * @return {Element|elem} The proper element
 */
const getNextActiveElement = (list, activeElement, shouldGetNext, isCycleAllowed) => {
  if (list.length === 0) {
    return activeElement
  }

  const enabled = list.filter(el => !isDisabled(el))
  if (enabled.length === 0) {
    // All elements are disabled, keep current
    return activeElement
  }

  let enabledIndex = enabled.indexOf(activeElement)
  if (enabledIndex === -1) {
    // activeElement is disabled; treat as starting point based on direction
    enabledIndex = shouldGetNext ? 0 : enabled.length - 1
  }

  let newIndex = enabledIndex + (shouldGetNext ? 1 : -1)
  const len = enabled.length
  if (isCycleAllowed) {
    newIndex = (newIndex + len) % len
  } else {
    if (newIndex < 0) {
      newIndex = 0
    } else if (newIndex >= len) {
      newIndex = len - 1
    }
  }

  return enabled[newIndex]
}
